import {APP_VERSION,PLAN_VERSION,BODY_FIELDS,GROUPS,DEFAULT_PLANS,EXERCISE_LABELS,SHIFT_LABELS,estimateMuscles} from './data.js';
import {readState,migrate,persist,makeBackup,clone,isoToday,localDate,dateISO,weekStart,nextDate,safeNum,fmt,displayDate,uniqueId,latestBodyValue} from './store.js';
import {atlasCard,muscleLoad} from './atlas.js';
import {lineChart,barChart} from './charts.js';
import {exerciseGuide,alternativesFor,BASIC_KNOWLEDGE,EXERCISE_GUIDES} from './lexicon.js';
import {STRENGTH_BENCHMARKS,LIFTS,STRENGTH_REFERENCES_UPDATED,estimated1rm,fmtStrength} from './strength.js';
import {EXERCISE_LIBRARY,EQUIPMENT,PROGRAM_TEMPLATES,templatePlans,templateLabels,findLibrary,libraryAlternatives} from './library.js';
import {orderedExercises,sessionSetCount,removeSetValues,previousSets,setPRs,summarizeWorkout,warmupProposal,plateDistribution,filterSince} from './training-tools.js';
import {PROGRAM_73_NAME,PROGRAM_73_LABELS,createProgram73,CUSTOM_73_GUIDES} from './plan73.js';

const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>isoToday();
const dateTime=(x)=>`${displayDate(x.date)}${x.created?' · '+new Date(x.created).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'}):''}`;
const {state:loaded,source}=readState();let state=loaded;
const ui={tab:'home',day:'A',editDay:'A',mode:'muscle',face:'front',muscle:'chest',week:weekStart(today()),month:today().slice(0,7),selectedDate:today(),bodyMetric:'weight',strengthEx:'',benchmarkPhase:'all',historyLimit:20,moreOpen:'backup',showSaved:false,moreSection:'wissen',strengthLift:'deadlift',strengthFilter:'all',progressDays:90,summaryId:null,libMuscle:'all',libEquip:'Alle',libQuery:''};
const hash=location.hash.replace('#','');if(['home','training','body','analyze','more','summary'].includes(hash))ui.tab=hash;
let messageTimer;
function notify(msg){let node=$('#toast');if(!node){node=document.createElement('div');node.id='toast';node.className='toast';node.setAttribute('role','status');document.body.append(node)}node.textContent=msg;node.hidden=false;clearTimeout(messageTimer);messageTimer=setTimeout(()=>node.hidden=true,3600)}
function save(){return persist(state)}
// Rest countdown uses absolute time, so backgrounding and reloads do not artificially extend the pause.
function restTotal(){return Math.max(30,Math.min(600,Math.round(Number(state.settings.restSeconds)||150)))}
function restRemaining(){const t=state.restTimer;if(!t)return 0;return t.running?Math.max(0,Math.ceil((t.endAt-Date.now())/1000)):Math.max(0,Number(t.remaining)||0)}
function formatRest(s){const n=Math.max(0,Math.floor(s));return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function exerciseRestSeconds(slotId){const v=Number(state.settings.exerciseRest?.[slotId]);return Number.isFinite(v)&&v>=30&&v<=600?v:restTotal()}
function startRest(exercise,slotId){if(state.settings.autoRest===false)return;const seconds=exerciseRestSeconds(slotId);state.restTimer={running:true,endAt:Date.now()+seconds*1000,remaining:seconds,totalSeconds:seconds,exercise,completed:false};save();updateRestDock()}
function updateRestDock(){let t=state.restTimer;let dock=$('#rest-dock');if(!dock){dock=document.createElement('aside');dock.id='rest-dock';dock.className='rest-dock';dock.setAttribute('aria-label','Satzpausentimer');document.body.appendChild(dock)}if(!t){dock.hidden=true;return}if(t.running&&restRemaining()<=0){t.running=false;t.remaining=0;t.completed=true;save()}dock.hidden=false;const remaining=restRemaining(),seconds=Number(t.totalSeconds)||restTotal();const value=dock.querySelector('.rest-value');if(!value||dock.dataset.exercise!==t.exercise||dock.dataset.status!==(t.completed?'done':t.running?'on':'off')){dock.dataset.exercise=t.exercise;dock.dataset.status=t.completed?'done':t.running?'on':'off';dock.innerHTML=`<div class="rest-dock-top"><div><small>${t.completed?'PAUSE BEENDET':t.running?'SATZPAUSE LÄUFT':'SATZPAUSE PAUSIERT'}</small><strong>${esc(t.exercise||'Trainingssatz')}</strong></div><button class="rest-close" data-rest-action="skip" aria-label="Timer schließen">×</button></div><div class="rest-dock-main"><strong class="rest-value" aria-live="off">${formatRest(remaining)}</strong><div class="rest-dock-actions"><button data-rest-action="toggle">${t.running?'Pause':'Weiter'}</button><button data-rest-action="plus">+30 s</button><button data-rest-action="skip">Fertig</button></div></div><div class="rest-progress"><i style="width:${Math.min(100,remaining/seconds*100)}%"></i></div>`}else{value.textContent=formatRest(remaining);const track=dock.querySelector('.rest-progress i');if(track)track.style.width=Math.min(100,remaining/seconds*100)+'%'}}
function restAction(action){const t=state.restTimer;if(!t)return;if(action==='skip'){state.restTimer=null}else if(action==='toggle'){if(t.completed){state.restTimer=null}else if(t.running){t.remaining=restRemaining();t.running=false;t.endAt=null}else{t.running=true;t.endAt=Date.now()+(Number(t.remaining)||restTotal())*1000}}else if(action==='plus'){t.remaining=restRemaining()+30;t.running=true;t.completed=false;t.endAt=Date.now()+t.remaining*1000}save();updateRestDock()}
setInterval(updateRestDock,500);
function effectiveExercise(ex,draft=state.draft){const swap=draft?.swaps?.[ex.id];return {...ex,displayName:swap?.name||ex.name,effectiveId:swap?.id||ex.catalogId||ex.id,swapped:!!swap,timeBased:!swap&&!!ex.timeBased}}
const cardStat=(title,value,sub='')=>`<div class="mini-stat"><span>${esc(title)}</span><strong>${esc(value)}</strong><small>${esc(sub)}</small></div>`;
const trainingDays=()=>Object.keys(state.plans||{}).filter(day=>Array.isArray(state.plans[day])).sort();
const planLabel=day=>state.settings.programLabels?.[day]||EXERCISE_LABELS[day]||('Training '+day);
const lastWorkouts=()=>[...state.workouts].sort((a,b)=>b.date.localeCompare(a.date)||(b.created||'').localeCompare(a.created||''));
function latestWeight(){const x=latestBodyValue(state.body,'weight');return x?fmt(x.weight)+' kg':'–'}
function lastCoach(){return state.coach?.checkins?.[today()]||null}
function coachAdvice(){const q=lastCoach();if(!q)return {kind:'neutral',title:'Tagescheck starten',message:'Schlaf, Ermüdung und Dienst eintragen. Die App gibt eine nachvollziehbare Orientierung, keine medizinische Freigabe.'};if(q.redflag)return {kind:'warning',title:'Training aussetzen',message:'Neue neurologische Beschwerden ärztlich abklären lassen. Bei Lähmungen oder Blasen-/Darmstörungen sofort Hilfe suchen.'};if(q.sleep<5||q.fatigue>=8||q.back>=7)return {kind:'warning',title:'Erholung priorisieren',message:'Sehr wenig Schlaf oder hohe Ermüdung dokumentiert. Keine schwere Einheit empfehlen.'};const last=lastWorkouts()[0];if(last&&last.date===today())return {kind:'good',title:'Training heute erledigt',message:'Du hast heute bereits eine Krafttrainingseinheit dokumentiert.'};const recent=lastWorkouts().filter(w=>localDate(w.date)>=localDate(nextDate(today(),-7)));const done=new Set(recent.map(w=>w.day));const suggested=trainingDays().find(day=>!done.has(day))||trainingDays().find(day=>!last||day!==last.day)||'A';return {kind:q.fatigue>=5||q.back>=5?'caution':'good',title:`Vorschlag: Einheit ${suggested}`,message:`${planLabel(suggested)}. ${q.fatigue>=5||q.back>=5?'Bei erhöhter Ermüdung Volumen reduzieren.':'Auf normale Erholung und Technik achten.'} Schicht: ${SHIFT_LABELS[q.shift]||'unbekannt'}.`,day:suggested}}
function nav(){return `<nav class="bottom-nav" aria-label="Hauptnavigation">${[['home','⌂','Home'],['training','▣','Training'],['body','◉','Körper'],['analyze','↗','Analyse'],['more','⚙','Mehr']].map(([id,icon,label])=>`<button data-tab="${id}" class="nav-btn ${ui.tab===id?'active':''}" ${ui.tab===id?'aria-current="page"':''}><span class="nav-symbol">${icon}</span><span>${label}</span></button>`).join('')}</nav>`}
function header(){return `<header class="top"><div class="topbar"><span class="brand"><span class="brand-mark">WA</span> WINTER ARC <b>OS</b></span><span class="status">LOCAL FIRST · V${APP_VERSION}</span></div><div class="head-title"><span class="eyebrow">BUILD THE BODY · TRACK THE PROCESS</span><h1>${{home:'Control Center',training:'Training',body:'Körperentwicklung',analyze:'Strength Intelligence',more:'Dein System',summary:'Trainingsabschluss'}[ui.tab]}</h1><p>${{home:'Heute zählt der nächste kontrollierte Fortschritt.',training:'Satz für Satz. Direkt dokumentieren.',body:'Umfänge, Gewicht und Muskelbelastung.',analyze:'Zahlen statt Bauchgefühl.',more:'Pläne, Regeneration, Export und Einstellungen.',summary:'Deine dokumentierten Trainingswerte.'}[ui.tab]}</p></div></header>`}
function render(resetScroll=false){
 const main=$('#app');if(!main)return;
 main.innerHTML=`<div class="shell">${header()}<main class="container">${({home:homePage,training:trainingPage,body:bodyPage,analyze:analyzePage,more:morePage,summary:summaryPage})[ui.tab]()}</main></div>${nav()}`;
 if(resetScroll)scrollTo({top:0,behavior:'instant'});
 updateRestDock();
}
function homePage(){
 const week=weekStart(today()),thisWeek=state.workouts.filter(w=>weekStart(w.date)===week),weight=latestWeight(),latest=lastWorkouts()[0],advice=coachAdvice();
 const suggestion=advice.day||(trainingDays().find(d=>!thisWeek.some(w=>w.day===d))||trainingDays()[0]||'A');
 const setCount=thisWeek.reduce((n,w)=>n+(w.sets?.length||0),0);
 return `<section class="dash-hero"><span class="eyebrow">DEIN NÄCHSTER SCHRITT</span><h2>${esc(planLabel(suggestion))}</h2><p>${esc(advice.title)} · ${esc(advice.message)}</p><div class="button-row"><button class="primary" data-start-day="${suggestion}">Training ${suggestion} öffnen →</button><button class="subtle" data-tab="analyze">Fortschritt ↗</button></div></section>
 <div class="stats-grid section-gap">${cardStat('Krafteinheiten',thisWeek.length+' / '+trainingDays().length,'Diese Woche')}${cardStat('Arbeitssätze',setCount,'Diese Woche')}${cardStat('Gewicht',weight,'Letzte Messung')}${cardStat('Letztes Training',latest?`Tag ${latest.day}`:'–',latest?displayDate(latest.date):'Noch keine Einheit')}</div>
 <div class="quick-links"><button data-tab="training">▣ Training</button><button data-tab="body">◉ Körperatlas</button><button data-tab="analyze">↗ Analysen</button><button data-tab="more" data-more-to="wissen">ⓘ Wissen</button></div>
 <div class="two-col section-gap"><section class="panel"><div class="section-header"><div><span class="eyebrow">LETZTE LEISTUNG</span><h2>${latest?`Tag ${esc(latest.day)} · ${displayDate(latest.date)}`:'Noch keine Einheit'}</h2></div></div>${latest?`<p>${latest.sets.length} Arbeitssätze · ${fmt(latest.sets.reduce((n,s)=>n+(s.holdSeconds?0:Number(s.weight||0)*Number(s.reps||0)),0),0)} kg Gesamtvolumen</p><button class="text-btn" data-show-summary="${esc(latest.id)}">Zusammenfassung öffnen ↗</button>`:'<p>Starte dein erstes Training und dokumentiere die Arbeitssätze.</p>'}</section>
 <section class="panel"><div class="section-header"><div><span class="eyebrow">WOCHE</span><h2>Dein Trainingskalender</h2></div><button class="text-btn" data-tab="analyze">Monatsansicht ↗</button></div>${miniCalendar()}</section></div>
 <section class="panel section-gap"><details class="dashboard-expand"><summary>Gewicht erfassen & Trend anzeigen</summary>${lineChart(state.body.filter(b=>Number(b.weight)>0).map(b=>({date:b.date,value:b.weight})),'kg',{trend:true})}<form id="quick-weight" class="inline-form"><label>Neue Messung <input type="number" name="weight" min="20" max="500" step="0.1" placeholder="z. B. 110,9" required></label><button class="primary" type="submit">Speichern</button></form></details></section>
 <section class="panel section-gap"><details class="dashboard-expand"><summary>Daily Coach · Schlaf, Schicht & Ermüdung</summary><p class="micro">Manuelle Orientierung, keine medizinische Risikobewertung.</p><form id="coach-form" class="form-grid compact"><label>Schicht<select name="shift">${Object.entries(SHIFT_LABELS).map(([v,l])=>`<option value="${v}" ${lastCoach()?.shift===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Schlaf (Std.)<input type="number" name="sleep" step="0.5" min="0" max="24" value="${lastCoach()?.sleep??7}" required></label><label>Ermüdung (0–10)<input type="number" name="fatigue" min="0" max="10" value="${lastCoach()?.fatigue??3}" required></label><label>Rücken (0–10)<input type="number" name="back" min="0" max="10" value="${lastCoach()?.back??1}" required></label><label class="inline-check full"><input type="checkbox" name="redflag" ${lastCoach()?.redflag?'checked':''}><span>Neue neurologische Warnsymptome</span></label><button class="primary full" type="submit">Check-in speichern</button></form></details></section><section class="panel section-gap"><details class="dashboard-expand"><summary>Optional: Morning Reset (5 Minuten)</summary><div class="check-list">${[['calves','Lockere Wadenbewegungen'],['rotation','Schulter-/Rumpfrotation'],['squat','Unterstützte Kniebeugeposition'],['seiza','Optionaler Fersensitz'],['breath','5–8 ruhige Atemzüge']].map(([id,label])=>`<label class="inline-check"><input type="checkbox" data-morning="${id}" ${(state.morning?.[today()]||[]).includes(id)?'checked':''}><span>${label}</span></label>`).join('')}</div><p class="micro">Nur schmerzfrei und freiwillig.</p></details></section>`;
}

function miniCalendar(){const start=nextDate(today(),-((localDate(today()).getDay()+6)%7));return `<div class="mini-week">${Array.from({length:7},(_,i)=>{const day=nextDate(start,i),w=state.workouts.filter(x=>x.date===day),r=state.runs.some(x=>x.date===day),b=state.body.some(x=>x.date===day);return `<button class="mini-day ${day===today()?'today':''}" data-calendar-date="${day}" data-open-calendar="1"><small>${['Mo','Di','Mi','Do','Fr','Sa','So'][i]}</small><strong>${Number(day.slice(8))}</strong><span>${w.map(x=>x.day).join('')}${r?'↝':''}${b?'○':''}</span></button>`}).join('')}</div>`}
function compactMusclePanel(){const load=muscleLoad(state.workouts,weekStart(today()));const items=Object.entries(load).sort((a,b)=>b[1].direct-a[1].direct).slice(0,7);return `<section class="panel"><div class="section-header"><div><span class="eyebrow">MUSCLE VOLUME</span><h2>Diese Woche</h2></div><button class="text-btn" data-tab="body">Atlas öffnen ↗</button></div>${barChart(items.map(([name,n])=>({label:GROUPS[name],value:n.direct})))}<p class="micro">Nur dokumentierte Arbeitssätze, keine geschätzte Erholung.</p></section>`}
function ensureDraft(){if(!state.draft||state.draft.day!==ui.day){state.draft={day:ui.day,date:today(),values:{},notes:'',warmup:{},order:[],skipped:[],setCounts:{},startedAt:new Date().toISOString()};save()}state.draft.order??=[];state.draft.skipped??=[];state.draft.setCounts??={};state.draft.values??={};state.draft.startedAt??=new Date().toISOString();return state.draft}
function selectedSetCount(ex,draft=state.draft){const reduced=state.settings.trainPhase!=='aufbau';const base=reduced?Math.min(Number(ex.sets)||1,2):Math.min(8,Number(ex.sets)||1);return sessionSetCount(ex,draft,base)}
function latestExercise(ex){return previousSets(state.workouts,ex.effectiveId)}
function lastExercise(ex){const found=latestExercise(ex);return found?`${displayDate(found.date)}: `+found.sets.map(s=>`${fmt(s.weight||0)} kg × ${s.holdSeconds?`${s.holdSeconds} s`:s.reps} (RIR ${s.rir===''?'–':s.rir??'–'})`).join(' · '):'Noch keine passenden Sätze erfasst'}
function activePlan(){return orderedExercises(state.plans[ui.day]||[],ensureDraft())}
function sessionCompletion(draft){const active=orderedExercises(state.plans[ui.day]||[],draft).filter(ex=>!draft.skipped.includes(ex.id));const planned=active.reduce((n,ex)=>n+selectedSetCount(ex,draft),0);const completed=active.reduce((n,ex)=>n+Array.from({length:selectedSetCount(ex,draft)},(_,j)=>draft.values[`${ex.id}#${j}`]?.done?1:0).reduce((a,b)=>a+b,0),0);return {active,planned,completed}}

function trainingPage(){const draft=ensureDraft(),{active,planned,completed}=sessionCompletion(draft);
 const all=orderedExercises(state.plans[ui.day]||[],draft),skipped=all.filter(ex=>draft.skipped.includes(ex.id));
 return `<div class="segmented section-gap">${trainingDays().map(d=>`<button data-day="${d}" class="${ui.day===d?'active':''}">Tag ${d}</button>`).join('')}</div>
 <section class="panel workout-overview"><div class="section-header"><div><span class="eyebrow">TRAINING ${ui.day} · LIVE</span><h2>${esc(planLabel(ui.day))}</h2></div><div class="progress-number">${completed}<small> / ${planned} Sätze</small></div></div><div class="meter"><span style="width:${planned?100*completed/planned:0}%"></span></div><div class="form-grid compact"><label>Datum<input type="date" data-draft-date value="${esc(draft.date)}"></label><label>Programm<input type="text" disabled value="${esc(state.settings.activeProgram==='legacy-1.2'?'Aus V1.2 übernommen':state.settings.activeProgram||'Eigener Plan')}"></label></div><p class="micro">Sätze & Übungsreihenfolge gelten nur für diese Einheit. Pausentimer nach jedem abgeschlossenen Arbeitssatz.</p></section>
 <section class="section-gap"><div class="section-header"><h2>Übungen</h2><button class="text-btn" data-tab="more" data-open-knowledge="1">Lexikon ↗</button></div>${active.map((ex,i)=>exerciseCard(ex,i,draft,active.length)).join('')}${skipped.length?`<details class="panel skipped-panel"><summary>Übersprungen (${skipped.length}) – wiederherstellen</summary>${skipped.map(ex=>`<div class="history-row"><strong>${esc(ex.name)}</strong><button class="tiny" data-restore-ex="${esc(ex.id)}">Wiederherstellen</button></div>`).join('')}</details>`:''}</section>
 <section class="panel section-gap"><details class="dashboard-expand" ${ui.calc?'open':''}><summary>Aufwärmsatz- & Scheibenrechner</summary><p class="micro">Unverbindlicher Einstiegsvorschlag für einen Arbeitssatz, anpassbar. Hantelscheiben gelten für eine Langhantel.</p><form id="warmup-form" class="form-grid compact"><label>Arbeitssatz (kg)<input type="number" min="1" max="500" step="0.5" name="target" value="${esc(ui.calc?.target??80)}" required></label><label>Stange (kg)<input type="number" min="0" max="50" step="0.5" name="bar" value="${esc(ui.calc?.bar??20)}" required></label><label>Aufwärm-Stufen (%)<input name="ratios" value="${esc(ui.calc?.ratios??'40,60,80')}" placeholder="40,60,80"></label><label>Scheiben (jeweils kg)<input name="plates" value="${esc(ui.calc?.plates??'25,20,15,10,5,2.5,1.25')}" placeholder="25,20,15,10,5,2.5,1.25"></label><button type="submit" class="subtle full">Berechnen</button></form>${ui.calc?warmupResult(ui.calc.target,ui.calc.bar,ui.calc.ratios,ui.calc.plates):''}</details></section>
 <section class="panel section-gap"><label class="field">Trainingsnotiz<textarea data-draft-notes placeholder="Technik, Energie, Gerätevariante, Beschwerden …">${esc(draft.notes||'')}</textarea></label><div class="button-row"><button class="primary" id="save-workout">Training abschließen</button><button class="subtle" id="clear-draft">Entwurf verwerfen</button></div><p class="micro">Nur abgehakte Arbeitssätze werden gespeichert. Übersprungene Übungen zählen nicht. Der Plan bleibt unverändert.</p></section>`;
}
function warmupResult(target,bar,ratios='40,60,80',plateList='25,20,15,10,5,2.5,1.25'){const steps=warmupProposal(target,ratios.split(',').map(x=>Number(x.trim())/100)),plates=plateDistribution(target,bar,plateList.split(',').map(x=>Number(x.trim())));return `<div class="calc-results"><strong>Aufwärmen:</strong> ${steps.map(s=>`${fmt(s.weight)} kg × ${s.reps} (${s.percent} % )`).join(' · ')}<div><strong>Scheiben pro Seite:</strong> ${plates.error?esc(plates.error):plates.result.map(x=>`${x.count}×${fmt(x.plate)} kg`).join(' + ')||'Keine'}${plates.exact?'':` · erreichbar: ${fmt(plates.achievedKg)} kg (Rest ${fmt(plates.remainderKg)})`}</div></div>`}

function exerciseCard(original,i,draft,total){
 const ex=effectiveExercise(original,draft),guide=CUSTOM_73_GUIDES[ex.effectiveId]||exerciseGuide(ex.effectiveId,ex.displayName),alts=[...new Map([...alternativesFor(original),...libraryAlternatives(ex)].map(a=>[a.id,a])).values()].filter(a=>a.id!==ex.effectiveId),count=selectedSetCount(original,draft),last=latestExercise(ex);
 const warm=Array.from({length:ex.warmups||0},(_,j)=>setRow(ex,j,draft,true,null)).join(''),sets=Array.from({length:count},(_,j)=>setRow(ex,j,draft,false,last?.sets?.[j]||null)).join('');
 return `<article class="exercise" id="ex-${esc(original.id)}"><div class="exercise-head"><div><span class="eyebrow">${String(i+1).padStart(2,'0')} / ${total} · ÜBUNG</span><h3>${esc(ex.displayName)}</h3>${ex.swapped?'<span class="swap-label">Heute getauscht</span>':''}<small>${esc(lastExercise(ex))}</small></div><span class="tag">${count} × ${esc(ex.reps)}</span></div>
 <div class="live-ex-actions"><button class="tiny" data-move-ex="${esc(original.id)}" data-direction="-1" ${i===0?'disabled':''} aria-label="Übung nach oben">↑</button><button class="tiny" data-move-ex="${esc(original.id)}" data-direction="1" ${i===total-1?'disabled':''} aria-label="Übung nach unten">↓</button><button class="tiny" data-skip-ex="${esc(original.id)}">Überspringen</button>${last?`<button class="tiny" data-fill-all="${esc(original.id)}">↙ Letzte Werte</button>`:''}</div>
 <div class="exercise-tools"><details class="exercise-guide"><summary>ⓘ Ausführung</summary><div class="exercise-info"><strong>${esc(guide.focus)}</strong><ul>${guide.cues.map(c=>`<li>${esc(c)}</li>`).join('')}</ul><p><b>Achtung:</b> ${esc(guide.avoid)}</p></div></details>
 <details class="exercise-swap"><summary>⇄ Alternative wählen</summary><p class="micro">Nur für diese Einheit. Wechsel nach abgeschlossenen Sätzen gesperrt.</p><input type="search" data-swap-search="${esc(original.id)}" placeholder="Alternative suchen …" aria-label="Alternativen durchsuchen"><select data-alternative="${esc(original.id)}" aria-label="Alternative für ${esc(original.name)}"><option value="">Original: ${esc(original.name)}</option>${alts.map(a=>`<option value="${esc(a.id)}" ${ex.effectiveId===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></details>
 <details class="exercise-guide"><summary>⚙ Einstellungen & persönliche Notizen</summary><div class="exercise-info"><label>Pause nach Arbeitssatz (Sek.)<input data-ex-rest="${esc(original.id)}" type="number" min="30" max="600" step="5" value="${exerciseRestSeconds(original.id)}"></label><label>Deine Geräteeinstellungen & Techniknotizen<textarea data-ex-note="${esc(ex.effectiveId)}" placeholder="z. B. Sitzhöhe 5, neutraler Griff, Kabelhöhe …">${esc(state.exerciseNotes?.[ex.effectiveId]||'')}</textarea></label><p class="micro">Notizen bleiben über Trainingseinheiten erhalten. Die Pause ist jederzeit je Übung anpassbar.</p></div></details></div>
 ${ex.rir?`<p class="rir-hint">RIR-Ziel: ${esc(ex.rir)}</p>`:''}${warm}${sets}<div class="set-actions"><button class="tiny" data-add-set="${esc(original.id)}" ${count>=20?'disabled':''}>+ Arbeitssatz</button><span>${count} geplante Arbeitssätze für heute</span></div></article>`;
}

function setRow(ex,j,draft,warm,prev){const key=`${ex.id}${warm?'#warm':''}#${j}`,v=draft.values?.[key]||{};
 return `<div class="set-row ${v.done?'done':''} ${warm?'warm':''}"><div class="set-title"><strong>${warm?'AUFWÄRMEN':'ARBEITSSATZ'} ${j+1}</strong><span>${esc(ex.reps)}</span>${!warm&&prev?`<button class="tiny last-set-copy" data-fill-prev="${esc(key)}" title="Werte aus dem letzten Training übernehmen">↙ ${fmt(prev.weight)} kg × ${esc(prev.reps)}${prev.rir!==''&&prev.rir!==undefined?' · RIR '+esc(prev.rir):''}</button>`:''}${!warm?`<button class="tiny danger" data-remove-set="${esc(key)}" aria-label="Satz ${j+1} entfernen">×</button>`:''}</div>
 <div class="set-grid"><label>kg<input data-set="${esc(key)}" data-field="weight" inputmode="decimal" placeholder="kg" value="${esc(v.weight??'')}"></label><label>${ex.timeBased?'Sek.':'Wdh.'}<input data-set="${esc(key)}" data-field="reps" type="number" min="0" max="150" placeholder="${ex.timeBased?'s':'Wdh.'}" value="${esc(v.reps??'')}"></label>${warm?'':`<label>RIR<select data-set="${esc(key)}" data-field="rir"><option value="">–</option>${[0,1,2,3,4,5].map(x=>`<option value="${x}" ${String(v.rir)===String(x)?'selected':''}>${x}</option>`).join('')}</select></label>`}<label class="set-done"><span>Fertig</span><input type="checkbox" data-set-check="${esc(key)}" ${v.done?'checked':''}></label></div>${warm?'':`<details class="set-method"><summary>Intensitätstechnik · ${v.method&&v.method!=='standard'?esc(v.method):'Normal'}</summary><label>Methode<select data-set="${esc(key)}" data-field="method">${[['standard','Normal'],['restpause','Rest-Pause'],['myoreps','Myo-Reps'],['partial','Lengthened Partials'],['onehalf','1,5 Wdh.']].map(([id,label])=>`<option value="${id}" ${(v.method||'standard')===id?'selected':''}>${label}</option>`).join('')}</select></label></details>`}</div>`;
}

function normalizeRecords(key){return [...state.body].filter(b=>Number(b[key])>0).sort((a,b)=>a.date.localeCompare(b.date)).map(b=>({date:b.date,value:Number(b[key])}))}
function bodyPage(){const metric=BODY_FIELDS.find(([id])=>id===ui.bodyMetric)||BODY_FIELDS[0];const metricRows=filterSince(normalizeRecords(metric[0]),ui.progressDays,today());const last=metricRows[metricRows.length-1];const lastW=latestBodyValue(state.body,'weight');return `<div class="two-col"><div>${atlasCard(state,{mode:ui.mode,face:ui.face,muscle:ui.muscle,week:ui.week})}</div><section class="panel"><div class="section-header"><div><span class="eyebrow">MEASURE & TRACK</span><h2>Neue Körpermessung</h2></div><span class="tag">PRIVAT</span></div><form id="body-form" class="form-grid"><label class="full">Datum<input type="date" name="date" value="${today()}" required></label>${BODY_FIELDS.map(([id,label,unit])=>`<label>${esc(label)} <small>${unit}</small><input name="${id}" type="number" step="0.1" min="0" max="500" placeholder="–"></label>`).join('')}<label class="full">Notiz (optional)<textarea name="note" placeholder="Morgens nüchtern, nach Training, Messbedingungen ..."></textarea></label><button class="primary full" type="submit">Messwerte speichern</button></form></section></div>
 <section class="panel section-gap"><div class="section-header"><div><span class="eyebrow">BODY CHART</span><h2>${metric[1]}</h2></div><span class="tag">${last?fmt(last.value)+' '+metric[2]:'Noch kein Wert'}</span></div>${historyRangeControl()}<label class="field">Diagramm auswählen<select id="body-metric">${BODY_FIELDS.map(([id,label])=>`<option value="${id}" ${id===ui.bodyMetric?'selected':''}>${esc(label)}</option>`).join('')}</select></label>${lineChart(metricRows,metric[2],{trend:metric[0]==='weight'})}<p class="micro">Gewicht und Umfang allein können Muskelaufbau, Fettzunahme oder Wassereinlagerungen nicht zuverlässig unterscheiden.</p></section>
 <section class="panel section-gap"><div class="section-header"><div><span class="eyebrow">LOGBOOK</span><h2>Messhistorie</h2></div><span class="tag">${state.body.length} Einträge</span></div>${[...state.body].sort((a,b)=>b.date.localeCompare(a.date)).map(b=>`<div class="history-row"><div><strong>${displayDate(b.date)}</strong><small>${b.weight?fmt(b.weight)+' kg':'Ohne Gewicht'}${b.waist?' · Bauch '+fmt(b.waist)+' cm':''}${b.note?' · '+esc(b.note):''}</small></div><button class="tiny danger" data-delete="body" data-id="${esc(b.id)}">Löschen</button></div>`).join('')||'<p class="empty">Noch keine Körpermessungen in der App.</p>'}</section>`}
function eventsForDate(date){return {workouts:state.workouts.filter(x=>x.date===date),runs:state.runs.filter(x=>x.date===date),body:state.body.filter(x=>x.date===date)}}
function calendar(){const [y,m]=ui.month.split('-').map(Number),first=new Date(y,m-1,1),days=new Date(y,m,0).getDate(),blank=(first.getDay()+6)%7,cells=Math.ceil((blank+days)/7)*7;return `<section class="panel"><div class="section-header"><div><span class="eyebrow">TRAINING HISTORY</span><h2>Kalender</h2></div><div class="month-nav"><button class="icon-button" data-month="-1">‹</button><strong>${first.toLocaleDateString('de-DE',{month:'long',year:'numeric'})}</strong><button class="icon-button" data-month="1">›</button></div></div><div class="calendar-grid">${['Mo','Di','Mi','Do','Fr','Sa','So'].map(x=>`<span class="weekday">${x}</span>`).join('')}${Array.from({length:cells},(_,i)=>{const d=i-blank+1;if(d<1||d>days)return '<span></span>';const iso=`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`,e=eventsForDate(iso);return `<button class="cal-day ${iso===today()?'today':''} ${iso===ui.selectedDate?'selected':''}" data-calendar-date="${iso}"><b>${d}</b><span>${e.workouts.map(w=>`<i class="cal-label">${w.day}</i>`).join('')}${e.runs.length?'<i class="cal-label cardio">↝</i>':''}${e.body.length?'<i class="cal-label measure">○</i>':''}</span></button>`}).join('')}</div>${(()=>{const e=eventsForDate(ui.selectedDate);return `<div class="selected-calendar"><strong>${displayDate(ui.selectedDate)}</strong>${e.workouts.map(w=>`<p>▣ Tag ${w.day}: ${w.sets?.length||0} Arbeitssätze</p>`).join('')}${e.runs.map(r=>`<p>↝ ${esc(r.type)}: ${fmt(r.minutes||0)} Min.</p>`).join('')}${e.body.map(b=>`<p>○ Körpermessung${b.weight?' · '+fmt(b.weight)+' kg':''}</p>`).join('')}${!e.workouts.length&&!e.runs.length&&!e.body.length?'<p>Keine Einträge für diesen Tag.</p>':''}</div>`})()}</section>`}
function strengthRows(){const m=new Map();for(const w of state.workouts){for(const s of w.sets||[]){if(s.holdSeconds||Number(s.weight)<=0||Number(s.reps)<=0)continue;const key=s.exerciseId||s.exercise;const prev=m.get(key)||{name:s.exercise,id:key,total:0,records:[],bestKg:0,bestVolume:0,bestE1rm:0,date:''};prev.total++;prev.records.push({...s,date:w.date});if(Number(s.weight)>prev.bestKg)prev.bestKg=Number(s.weight);const volume=Number(s.weight)*Number(s.reps);if(volume>prev.bestVolume)prev.bestVolume=volume;if(Number(s.reps)<=10){const score=Number(s.weight)*(1+Number(s.reps)/30);if(score>prev.bestE1rm)prev.bestE1rm=score}if(w.date>prev.date)prev.date=w.date;m.set(key,prev)}}return [...m.values()].sort((a,b)=>a.name.localeCompare(b.name,'de'))}
function personalStrengthFor(lift){
 const manual=(state.strengthEntries||[]).filter(e=>e.lift===lift).map(e=>({...e,source:'manual'}));
 const inferred=[];
 const match=name=>{const n=String(name||'').toLowerCase();if(lift==='deadlift')return /kreuzheben|deadlift/.test(n)&&!/maschine|rack.pull|rumänisch|romanian|rdl|stiff/.test(n);
 if(lift==='squat')return /kniebeuge|barbell.squat/.test(n)&&!/hack|maschine|split|beinpresse|smith|multipresse|front/.test(n);
 if(lift==='bench')return /bankdrücken/.test(n)&&!/schräg|kurzhantel|multipresse|smith|maschine|brustpresse/.test(n);
 return /log.lift|log.press|loglift/.test(n)};
 for(const w of state.workouts)for(const e of w.sets||[])if(!e.holdSeconds&&match(e.exercise))inferred.push({id:`${w.id}:${e.set}`,lift,date:w.date,weight:Number(e.weight),reps:Number(e.reps),source:'workout'});
 return [...manual,...inferred].filter(e=>e.weight>0&&e.reps>0).sort((a,b)=>b.date.localeCompare(a.date));
}
function strengthBenchmarkPanel(){const lift=ui.strengthLift,records=STRENGTH_BENCHMARKS.filter(b=>b.lift===lift).filter(b=>ui.strengthFilter==='all'||(ui.strengthFilter==='contest'?b.level==='Wettkampf':b.level!=='Wettkampf'));
 const mine=personalStrengthFor(lift),best=[...mine].filter(e=>estimated1rm(e.weight,e.reps)).sort((a,b)=>estimated1rm(b.weight,b.reps)-estimated1rm(a.weight,a.reps))[0],calc=best?estimated1rm(best.weight,best.reps):null;
 return `<section class="panel section-gap" id="strength-comparison"><div class="section-header"><div><span class="eyebrow">STRENGTH BENCHMARKS · QUELLENBASIERT</span><h2>Legendäre Kraftleistungen</h2></div><span class="tag">Stand ${STRENGTH_REFERENCES_UPDATED}</span></div>
 <p class="micro">Hier vergleichen wir <b>Kraftwerte</b>, nicht Körpergewicht. Historische Trainingsvideos und Wettkampfergebnisse werden getrennt gekennzeichnet. Keine erfundenen Leistungsperzentile.</p>
 <div class="strength-controls"><label>Disziplin<select id="strength-lift">${Object.entries(LIFTS).map(([id,name])=>`<option value="${id}" ${lift===id?'selected':''}>${name}</option>`).join('')}</select></label><label>Quelle<select id="strength-filter">${[['all','Alle Leistungen'],['contest','Wettkämpfe'],['training','Gym / Video']].map(([id,label])=>`<option value="${id}" ${ui.strengthFilter===id?'selected':''}>${label}</option>`).join('')}</select></label></div>
 <div class="strength-personal"><div><small>DEIN BESTER DOKUMENTIERTER WERT</small><strong>${best?`${fmtStrength(best.weight)} kg × ${best.reps}`:'Noch kein Wert'}</strong><span>${calc?`Rechnerisches e1RM: ${fmtStrength(calc)} kg (Schätzung)`: 'Eigene Leistung unten erfassen'}</span></div><div><small>DEIN VERLAUF</small><strong>${mine.length} Einträge</strong><span>${mine.length?'Aus Training und eigenen Kraftwerten':'Keine Vergleichsdaten vorhanden'}</span></div></div>
 <div class="legend-list">${records.length?records.map(r=>`<article class="legend-card"><div class="legend-head"><div><strong>${esc(r.athlete)}</strong><small>${esc(r.competition)}</small></div><div class="legend-number">${fmtStrength(r.weightKg)} <span>kg</span>${r.reps>1?`<small> × ${r.reps} Wdh.</small>`:''}</div></div><div class="legend-meta"><span>${esc(r.level)}</span><span>${esc(r.quality)}</span></div>${calc?`<div class="legend-progress"><i style="width:${Math.min(100,100*calc/r.weightKg).toFixed(1)}%"></i></div><small class="legend-ratio">Dein rechnerisches e1RM: ${fmtStrength(calc/r.weightKg*100)} % dieser Last – nur ein Zahlenverhältnis.</small>`:''}<details><summary>Regeln & Quelle</summary><p>${esc(r.rules)}</p><a href="${esc(r.source)}" target="_blank" rel="noopener noreferrer">Beleg ansehen ↗</a></details></article>`).join(''):'<p class="empty">Keine Werte für diese Filterauswahl.</p>'}</div>
 <div class="notice warning"><strong>Fairness-Hinweis:</strong> Strongman-Kreuzheben (z. B. mit Anzug/Zughilfen), Raw-Powerlifting und Bodybuilding-Trainingsvideos sind keine identischen Tests. Der bloße Kilogrammwert ergibt keinen Rang oder Perzentil. Geschätzte 1RM-Werte sind keine echten Maximalversuche.</div>
 <details class="strength-add"><summary>+ Eigenen Kraftwert hinzufügen</summary><form id="strength-entry-form" class="form-grid"><label>Disziplin<select name="lift">${Object.entries(LIFTS).map(([id,name])=>`<option value="${id}" ${id===lift?'selected':''}>${name}</option>`).join('')}</select></label><label>Datum<input name="date" type="date" value="${today()}" required></label><label>Gewicht (kg)<input name="weight" type="number" inputmode="decimal" step="0.5" min="1" max="650" required></label><label>Wiederholungen<input name="reps" type="number" min="1" max="30" value="1" required></label><label class="full">Regeln / Ausrüstung / Notiz<input name="note" maxlength="180" placeholder="z. B. ohne Zughilfen, Touch & Go"></label><button class="primary full" type="submit">Kraftleistung speichern</button></form><p class="micro">Kein 1RM-Test notwendig. Nur tatsächlich ausgeführte Leistungen dokumentieren.</p></details>
 ${mine.length?`<details class="strength-add"><summary>Meine ${mine.length} Vergleichswerte anzeigen</summary>${mine.map(x=>`<div class="history-row"><div><strong>${fmtStrength(x.weight)} kg × ${x.reps}</strong><small>${displayDate(x.date)} · ${x.source==='manual'?'Manuell':'Trainingslogger'}${x.note?' · '+esc(x.note):''}</small></div>${x.source==='manual'?`<button class="tiny danger" data-delete="strengthEntries" data-id="${esc(x.id)}">Löschen</button>`:''}</div>`).join('')}</details>`:''}
 </section>`;}
function weeklyVolumeRecords(){const byWeek=new Map();for(const w of state.workouts){const key=weekStart(w.date);byWeek.set(key,(byWeek.get(key)||0)+(w.sets||[]).reduce((acc,x)=>acc+(x.holdSeconds?0:Number(x.weight||0)*Number(x.reps||0)),0))}return filterSince([...byWeek].map(([date,value])=>({date,value})),ui.progressDays,today());}
function analyzePage(){const rows=strengthRows();if(!rows.some(x=>x.id===ui.strengthEx))ui.strengthEx=rows[0]?.id||'';const selected=rows.find(x=>x.id===ui.strengthEx),strengthHistory=filterSince((selected?.records||[]).filter(x=>Number(x.weight)>0).sort((a,b)=>a.date.localeCompare(b.date)).map(x=>({date:x.date,value:Number(x.weight)})),ui.progressDays,today()),pr=selected?setPRs(state.workouts,selected.id):null;return `${strengthBenchmarkPanel()}<div class="two-col section-gap">${calendar()}<section class="panel"><div class="section-header"><div><span class="eyebrow">STRENGTH DNA</span><h2>Persönliche Bestleistungen</h2></div><span class="tag">PRIVATE RANKING</span></div><label class="field">Übung<select id="strength-ex"><option value="">${rows.length?'Übung auswählen':'Noch keine Trainingseinheiten'}</option>${rows.map(x=>`<option value="${esc(x.id)}" ${ui.strengthEx===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>${selected?`<div class="stats-grid compact">${cardStat('Höchste Satzlast',fmt(selected.bestKg)+' kg')}${cardStat('Volumenrekord',fmt(selected.bestVolume,0)+' kg×Wdh.')}${cardStat('e1RM (≤10 Wdh.)',selected.bestE1rm?fmt(selected.bestE1rm)+' kg':'–','Epley-Schätzung')}${cardStat('Wdh. bei Maxlast',pr?.bestAtWeight?pr.bestAtWeight.reps+' × '+fmt(pr.bestAtWeight.weight)+' kg':'–')}${cardStat('Sitzungsvolumen-PR',pr?.bestSession?fmt(pr.bestSession.volume,0)+' kg':'–')}${cardStat('Absolvierte Sätze',String(selected.total))}</div>${historyRangeControl()}${lineChart(strengthHistory,'kg')}`:'<p class="empty">Erfasse zuerst ein Training.</p>'}<p class="micro">Bestleistungen aus Trainingslogs. e1RM ist eine Schätzung. Maschinenwerte sind nicht direkt mit anderen Geräten oder Wettkampfrekorden vergleichbar.</p><div class="line"></div><h3>Bevölkerungs-Perzentile</h3><p>Noch nicht aktiviert: Dafür benötigen wir repräsentative Datensätze und vergleichbare Bewegungsstandards. Das separate Strength-Legends-Archiv zeigt historische Einzelrekorde, keine Rangplatz-Prozentile.</p></section></div>
 <section class="panel section-gap"><div class="section-header"><div><span class="eyebrow">WORKLOAD TREND</span><h2>Trainingsvolumen nach Woche</h2></div></div>${historyRangeControl()}${lineChart(weeklyVolumeRecords(),'kg×Wdh.')}<p class="micro">Summe aus Satzgewicht × Wiederholungen pro Kalenderwoche. Gerätegewichte und Übungswechsel beeinflussen den Verlauf; kein Maß für Muskelwachstum.</p></section>
 <section class="panel section-gap"><div class="section-header"><div><span class="eyebrow">MUSCLE ANALYTICS</span><h2>Wochenvolumen</h2></div><span class="tag">Direkte Sätze</span></div>${barChart(Object.entries(muscleLoad(state.workouts,ui.week)).map(([id,x])=>({label:GROUPS[id],value:x.direct})).sort((a,b)=>b.value-a.value))}<div class="week-nav"><button class="icon-button" data-week="-7">‹</button><span>${displayDate(ui.week)} – ${displayDate(nextDate(ui.week,6))}</span><button class="icon-button" data-week="7">›</button></div><p class="micro">Heatmap und Balken verwenden die gleiche Übung→Muskel-Zuordnung. Für Übungen mit manuell abweichenden Gerätevarianten sind die Ergebnisse nur Näherungen.</p></section>
 <section class="panel section-gap"><div class="section-header"><div><span class="eyebrow">WORKOUT ARCHIVE</span><h2>Trainingshistorie</h2></div><span class="tag">${state.workouts.length} Einheiten</span></div>${lastWorkouts().slice(0,ui.historyLimit).map(w=>`<details class="history-detail"><summary><strong>Tag ${w.day} · ${displayDate(w.date)}</strong><span>${w.sets?.length||0} Sätze</span></summary><div class="detail-body">${(w.sets||[]).map(s=>`<div class="set-history"><strong>${esc(s.exercise)}</strong><span>${fmt(s.weight)} kg × ${s.holdSeconds?`${s.holdSeconds} s`:s.reps} · RIR ${esc(s.rir===''?'–':s.rir??'–')} · ${esc(s.method||'standard')}</span></div>`).join('')}${w.notes?`<p class="micro">${esc(w.notes)}</p>`:''}<button class="tiny" data-show-summary="${esc(w.id)}">Zusammenfassung</button><button class="tiny danger" data-delete="workouts" data-id="${esc(w.id)}">Einheit löschen</button></div></details>`).join('')||'<p class="empty">Noch keine Krafttrainings erfasst.</p>'}</section>`;
}
function historyRangeControl(){return `<div class="range-tabs" aria-label="Zeitraum wählen">${[[30,'30 T'],[90,'90 T'],[180,'180 T'],[0,'Gesamt']].map(([n,label])=>`<button data-range="${n}" class="${ui.progressDays===n?'active':''}" aria-pressed="${ui.progressDays===n}">${label}</button>`).join('')}</div>`}
function exerciseDirectory(editable=false){const cards=EXERCISE_LIBRARY.map(ex=>{const g=exerciseGuide(ex.id,ex.name);const alts=libraryAlternatives(ex).slice(0,4).map(a=>a.name).join(' · ');return `<details class="library-item" data-library-item data-search-text="${esc((ex.name+' '+ex.muscle+' '+ex.equipment).toLocaleLowerCase('de-DE'))}" data-library-muscle="${esc(ex.muscle)}" data-library-equipment="${esc(ex.equipment)}"><summary><strong>${esc(ex.name)}</strong><small>${esc(GROUPS[ex.muscle]||ex.muscle)} · ${esc(ex.equipment)}</small></summary><p>${esc(g.focus)}</p><ul>${g.cues.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><p class="micro"><strong>Alternativen:</strong> ${esc(alts||'Keine passenden hinterlegt')}</p>${editable?`<button class="tiny" data-add-library="${esc(ex.id)}">+ Zu Tag ${esc(ui.editDay)} hinzufügen</button>`:''}</details>`}).join('');return `<div class="library-controls"><input data-library-search type="search" placeholder="Übung suchen …"><select data-library-muscle aria-label="Muskelgruppe"><option value="all">Alle Muskeln</option>${Object.entries(GROUPS).map(([id,label])=>`<option value="${id}">${esc(label)}</option>`).join('')}</select><select data-library-equipment aria-label="Gerät"><option value="Alle">Alle Geräte</option>${EQUIPMENT.filter(v=>v!=='Alle').map(v=>`<option>${esc(v)}</option>`).join('')}</select></div><div class="library-list">${cards}</div><p class="micro">Mehr als ${EXERCISE_LIBRARY.length} Offline-Übungsvarianten. Gewichte verschiedener Geräte nicht automatisch vergleichen.</p>`}
function programPanel(){return `<section class="panel section-gap"><div class="section-header"><div><span class="eyebrow">PROGRAM LIBRARY</span><h2>Trainingsplan-Vorlagen</h2></div><span class="tag">3 TRAININGSTAGE</span></div><p>Ganzkörper, Upper/Lower, Push/Pull/Legs oder Kraftbasis. Jede Vorlage ist nach Aktivierung frei bearbeitbar. Ein Planwechsel löscht keine früheren Trainingseinheiten.</p><form id="template-form" class="form-grid compact"><label>Vorlage<select name="template">${Object.entries(PROGRAM_TEMPLATES).map(([id,v])=>`<option value="${id}">${esc(v.name)}</option>`).join('')}</select></label><button class="subtle" type="submit">Vorlage aktivieren</button></form><p class="micro">Vor einer Änderung Backup exportieren. Upper/Lower ist eine 3-Tage-Variante (Upper/Lower/Upper), keine automatische 4-Tage-Rotation.</p></section><section class="panel section-gap"><div class="section-header"><div><span class="eyebrow">EXERCISE LIBRARY</span><h2>Übung zu Tag ${esc(ui.editDay)} hinzufügen</h2></div></div>${exerciseDirectory(true)}</section>`}
function summaryPage(){const w=state.workouts.find(x=>x.id===ui.summaryId)||lastWorkouts()[0];if(!w)return `<section class="panel"><h2>Noch keine Trainingseinheit gespeichert</h2><button class="primary" data-tab="training">Zum Training</button></section>`;
 const previous=state.workouts.filter(x=>x.id!==w.id&&(x.date<w.date||(x.date===w.date&&String(x.created||'')<String(w.created||''))));const summary=summarizeWorkout(w,previous);const muscles=new Map();for(const s of w.sets||[])for(const [g,credit] of estimateMuscles(s.exerciseId,s.exercise))if(credit===1)muscles.set(g,(muscles.get(g)||0)+1);
 const byExercise=new Map();for(const s of w.sets||[]){const x=byExercise.get(s.exercise)||[];x.push(s);byExercise.set(s.exercise,x)}
 return `<section class="panel finish-summary"><span class="eyebrow">TRAINING ABGESCHLOSSEN</span><h2>Tag ${esc(w.day)} · ${displayDate(w.date)}</h2><div class="stats-grid">${cardStat('Arbeitssätze',String(summary.sets))}${cardStat('Dauer',summary.durationMinutes!==null?summary.durationMinutes+' Min.':'Nicht erfasst')}${cardStat('Gesamtvolumen',fmt(summary.volume,0)+' kg','Last × Wiederholungen')}${cardStat('Übungen',String(byExercise.size))}</div><h3>Persönliche Bestleistungen</h3>${summary.prs.length?`<ul>${summary.prs.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p class="micro">Für diese Einheit kein neuer dokumentierter Rekord nach den vorhandenen Daten. Gerätevarianten bleiben getrennt.</p>'}<h3>Trainierte Muskelgruppen</h3>${muscles.size?`<div class="muscle-pills">${[...muscles].map(([g,n])=>`<span>${esc(GROUPS[g]||g)} · ${n} Sätze</span>`).join('')}</div>`:'<p>Keine eindeutige Muskelzuordnung vorhanden.</p>'}<h3>Satzübersicht</h3>${[...byExercise].map(([name,sets])=>`<div class="history-row"><div><strong>${esc(name)}</strong><small>${sets.map(s=>`${fmt(s.weight)} kg × ${s.holdSeconds?`${s.holdSeconds} s`:s.reps}`).join(' · ')}</small></div></div>`).join('')}<p class="micro">Volumen ist die Summe von Satzgewicht × Wiederholungen, keine Messung des physiologischen Trainingsreizes. Für Einträge älterer Versionen ist keine Trainingsdauer verfügbar.</p><div class="button-row"><button class="primary" data-tab="home">Zum Dashboard</button><button class="subtle" data-tab="analyze">Analyse</button></div></section>`;
}
function knowledgePage(){
 const glossary=BASIC_KNOWLEDGE.map(k=>`<details class="knowledge-item" data-knowledge-item data-search-text="${esc((k.title+' '+k.category+' '+k.summary).toLowerCase())}"><summary><span>${esc(k.title)}</span><small>${esc(k.category)}</small></summary><p>${esc(k.summary)}</p><ul>${k.details.map(v=>`<li>${esc(v)}</li>`).join('')}</ul></details>`).join('');
 const exercises=[...new Map(Object.values(state.plans).flat().map(ex=>[ex.id,ex])).values()];
 const guides=exercises.map(ex=>{const v=exerciseGuide(ex.id,ex.name);return `<details class="knowledge-item" data-knowledge-item data-search-text="${esc((ex.name+' '+v.focus).toLowerCase())}"><summary><span>${esc(ex.name)}</span><small>Übungsführung</small></summary><p><b>Zielmuskeln:</b> ${esc(v.focus)}</p><ul>${v.cues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p><b>Vermeiden:</b> ${esc(v.avoid)}</p></details>`}).join('');
 return `<section class="panel section-gap"><div class="section-header"><div><span class="eyebrow">MINI-LEXIKON · OFFLINE</span><h2>Bodybuilding-Wissen</h2></div><span class="tag">7 Themen</span></div><input id="knowledge-search" type="search" placeholder="Wissen oder Übung suchen …" aria-label="Lexikon durchsuchen"><h3 class="lexicon-heading">Grundlagen</h3>${glossary}<h3 class="lexicon-heading">Übungen deines Plans</h3>${guides}<details class="directory-expand"><summary>Gesamte Übungsbibliothek durchsuchen (${EXERCISE_LIBRARY.length})</summary>${exerciseDirectory(false)}</details><p class="micro">Die Kurzanleitungen sind keine Ersatzlösung für eine individuelle Technikbegutachtung. Trainiere schmerzfrei und überprüfe Geräteeinstellungen vor Ort.</p></section>`;
}
function morePage(){
 const sections={
  wissen:()=>knowledgePage(),
  plan:()=>` <section class="panel section-gap"><div class="section-header"><div><span class="eyebrow">PROGRAM</span><h2>Trainingsplan</h2></div><span class="tag">${esc(state.settings.activeProgram)}</span></div><p>Aktives Programm: ${esc(state.settings.activeProgram)}. Die bestätigte persönliche WINTER ARC 7.3 Vorlage enthält fünf Trainingstage. Ein Planwechsel erhält abgeschlossene Trainingseinheiten, ersetzt jedoch die aktuelle Planauswahl.</p><div class="button-row"><button class="primary" id="apply-v73">7.3 · 5-Tage-Plan aktivieren</button><button class="subtle" id="export-data-alt">Vorher Backup</button></div><div class="button-row"><button class="subtle" id="apply-v52">Alten 5.2-Plan aktivieren</button>${state.settings.planArchive?'<button class="subtle" id="restore-plan">Vorherigen Plan wiederherstellen</button>':''}</div><div class="segmented">${trainingDays().map(d=>`<button data-edit-day="${d}" class="${ui.editDay===d?'active':''}">Tag ${d}</button>`).join('')}</div>${(state.plans[ui.editDay]||[]).map(ex=>`<div class="plan-edit"><input data-edit="${esc(ex.id)}" data-prop="name" aria-label="Übungsname" value="${esc(ex.name)}"><input type="number" data-edit="${esc(ex.id)}" data-prop="sets" min="1" max="8" aria-label="Sätze" value="${esc(ex.sets)}"><input data-edit="${esc(ex.id)}" data-prop="reps" aria-label="Wiederholungen" value="${esc(ex.reps)}"><button class="tiny danger" data-remove-ex="${esc(ex.id)}" aria-label="Übung löschen">×</button></div>`).join('')}<div class="button-row"><button class="subtle" id="add-ex">+ Übung</button></div><p class="micro">Änderungen am Plan beeinflussen nur zukünftige Einheiten. Für eine korrekte Heatmap neue Übungen eindeutig benennen.</p></section>${programPanel()}
 <section class="panel section-gap"><div class="section-header"><div><span class="eyebrow">TRAINING LEVEL</span><h2>Volumensteuerung</h2></div></div><div class="segmented"><button data-phase="einstieg" class="${state.settings.trainPhase!=='aufbau'?'active':''}">Einstieg (reduziert)</button><button data-phase="aufbau" class="${state.settings.trainPhase==='aufbau'?'active':''}">Aufbau (voll)</button></div><p class="micro">Kein automatischer Sprung auf hohe Umfänge. Nach Erkrankung und bei Beschwerden Training reduzieren.</p></section><section class="panel section-gap"><div class="section-header"><div><span class="eyebrow">REST TIMER</span><h2>Satzpausen</h2></div><span class="tag">STANDARD 2:30</span></div><form id="rest-settings" class="form-grid"><label>Dauer pro Arbeitssatz (Sekunden)<input type="number" name="seconds" min="30" max="600" step="5" value="${restTotal()}" required></label><label class="inline-check"><input type="checkbox" name="autoRest" ${state.settings.autoRest!==false?'checked':''}><span>Nach jedem Satz automatisch starten</span></label><button type="submit" class="primary full">Timer-Einstellung speichern</button></form><p class="micro">Aufwärmsätze starten keinen Timer. Der Timer bleibt beim Wechsel zwischen den App-Seiten sichtbar und kann jederzeit pausiert, verlängert oder geschlossen werden.</p></section>`,
  tracking:()=>` <div class="two-col section-gap"><section class="panel"><div class="section-header"><div><span class="eyebrow">CARDIO & RUN</span><h2>Ausdauer erfassen</h2></div></div><form id="run-form" class="form-grid"><label>Datum<input name="date" type="date" value="${today()}" required></label><label>Einheit<select name="type"><option value="easy">Easy Run</option><option value="zone2">Zone 2</option><option value="long">Long Run</option><option value="airbike">AirBike 4×4</option></select></label><label>Distanz (km; AirBike leer)<input name="distance" type="number" step="0.01" min="0"></label><label>Dauer (Min.)<input name="minutes" type="number" step="0.1" min="1" required></label><label>Ø Puls (optional)<input name="hr" type="number" min="0" max="240"></label><label>Anstrengung 1–10<input name="rpe" type="number" min="1" max="10" value="3"></label><label class="full">Notiz<textarea name="note" placeholder="Laufgefühl, Knie, Rücken ..."></textarea></label><button class="primary full" type="submit">Ausdauereinheit speichern</button></form><div class="compact-list">${[...state.runs].reverse().slice(0,5).map(r=>`<div class="history-row"><div><strong>${esc(r.type)} · ${displayDate(r.date)}</strong><small>${fmt(r.minutes)} Min.${r.distance?' · '+fmt(r.distance)+' km':''}</small></div><button class="tiny danger" data-delete="runs" data-id="${esc(r.id)}">×</button></div>`).join('')}</div></section>
 <section class="panel"><div class="section-header"><div><span class="eyebrow">SHIFT & RECOVERY</span><h2>Dienst / Rücken</h2></div></div><form id="duty-form" class="form-grid"><label>Datum<input name="date" type="date" value="${today()}" required></label><label>Schicht<select name="shift"><option>Früh</option><option>Tag</option><option>Nacht</option><option>Frei</option></select></label><label>Schutzweste (Std.)<input name="vest" type="number" step="0.5" min="0"></label><label>Rücken (0–10)<input name="back" type="number" min="0" max="10" value="0"></label><label>Schlaf (Std.)<input name="sleep" type="number" step="0.5" min="0" max="24"></label><label class="full">Notiz<textarea name="note" placeholder="Verspannungen, Beschwerden ..."></textarea></label><button class="primary full" type="submit">Diensteintrag speichern</button></form><p class="micro">Kein medizinischer Risikoscore. Bei neurologischen Warnsymptomen medizinisch abklären lassen.</p></section></div>
 <section class="panel section-gap"><div class="section-header"><div><span class="eyebrow">GOALS</span><h2>Langfristige Ziele</h2></div></div><form id="settings-form" class="form-grid"><label>Halbmarathon-Ziel<input name="raceDate" type="date" value="${esc(state.settings.raceDate||'')}"></label><label>Zieltempo (mm:ss/km)<input name="goalPace" value="${esc(state.settings.goalPace||'5:30')}" pattern="[0-9]+:[0-5][0-9]"></label><label class="full">Physique-Ziel<input name="goal" value="${esc(state.settings.goal||'Offseason Mass')}"></label><button class="primary full" type="submit">Ziele speichern</button></form></section>`,
  daten:()=>`<section class="panel"><div class="section-header"><div><span class="eyebrow">DATA CONTROL</span><h2>Backup & Import</h2></div><span class="tag">OFFLINE</span></div><p>Deine Trainings-, Körper- und Schichtdaten werden ausschließlich auf diesem Gerät gespeichert. Weder GitHub noch die App bekommen automatisch Zugriff darauf.</p><div class="notice warning"><strong>Vor jedem Update:</strong> JSON-Backup erstellen und außerhalb der App speichern. Wenn du ein Backup importierst, werden die derzeitigen V2-Daten ersetzt. Der alte V1-Speicher wird dabei nicht gelöscht.</div><div class="button-row"><button class="primary" id="export-data">Backup exportieren</button><button class="subtle" id="import-trigger">JSON importieren</button></div><input id="import-file" type="file" accept="application/json,.json" hidden><p class="micro">Akzeptiert alte Version-1-Backups und neue Version-2-Backups. Import ersetzt die aktuellen V2-Daten erst nach Bestätigung.</p></section>
 <section class="panel section-gap"><h2>Datenschutz & System</h2><p class="micro">WINTER ARC OS ${APP_VERSION} · Offlinefähige PWA. Kein Account, kein Tracking, keine Cloud. Personenbezogene Gesundheitsangaben niemals in das öffentliche GitHub-Repository hochladen.</p><button class="danger-outline" id="clear-v2">Alle V2-Daten löschen</button></section>`
 };
 const tabs=[['wissen','Wissen'],['plan','Plan'],['tracking','Tracking'],['daten','Backup']];
 return `<div class="segmented more-menu section-gap" role="group" aria-label="Einstellungen und Wissen">${tabs.map(([id,label])=>`<button data-more-section="${id}" class="${ui.moreSection===id?'active':''}" aria-pressed="${ui.moreSection===id}">${label}</button>`).join('')}</div>${(sections[ui.moreSection]||sections.wissen)()}`;
}

function saveStrengthEntry(form){const f=new FormData(form),weight=safeNum(f.get('weight')),reps=Math.round(safeNum(f.get('reps'))),lift=String(f.get('lift')||'');
 if(!LIFTS[lift]||!Number.isFinite(weight)||weight<=0||weight>650||!Number.isFinite(reps)||reps<1||reps>30){notify('Kraftwert, Übung und Wiederholungen prüfen.');return}
 state.strengthEntries??=[];state.strengthEntries.push({id:uniqueId(),date:String(f.get('date')||today()),lift,weight,reps,note:String(f.get('note')||'').slice(0,180),created:new Date().toISOString()});save();ui.strengthLift=lift;render();notify('Persönlichen Kraftwert gespeichert.');}
function saveRestSettings(form){const f=new FormData(form),seconds=Math.round(safeNum(f.get('seconds')));if(!Number.isFinite(seconds)||seconds<30||seconds>600){notify('Timer zwischen 30 und 600 Sekunden einstellen.');return}state.settings.restSeconds=seconds;state.settings.autoRest=f.has('autoRest');save();render();notify('Satzpausen-Einstellung gespeichert.');}
function saveWorkout(){const d=ensureDraft(),sets=[],warmups=[];
 for(const slot of orderedExercises(state.plans[ui.day]||[],d)){
  if(d.skipped.includes(slot.id))continue;const ex=effectiveExercise(slot,d);
  for(let i=0;i<selectedSetCount(slot,d);i++){
   const v=d.values[`${slot.id}#${i}`];if(!v?.done)continue;
   const weight=safeNum(v.weight),reps=safeNum(v.reps);if(!Number.isFinite(weight)||weight<0||!Number.isFinite(reps)||reps<=0){notify('Abgehakte Sätze brauchen gültige Gewichte und Wiederholungen.');return}
   sets.push({exercise:ex.displayName,exerciseId:ex.effectiveId,originalExerciseId:ex.swapped?slot.id:undefined,set:i+1,weight,reps,holdSeconds:ex.timeBased?reps:undefined,rir:v.rir??'',method:v.method||'standard'});
  }
  for(let i=0;i<(slot.warmups||0);i++){const v=d.values[`${slot.id}#warm#${i}`];if(!v?.done)continue;warmups.push({exercise:ex.displayName,weight:Number(v.weight)||0,reps:Number(v.reps)||0})}
 }
 if(!sets.length){notify('Bitte mindestens einen Arbeitssatz abhaken.');return}
 const started=Date.parse(d.startedAt);const durationSeconds=Number.isFinite(started)?Math.max(0,Math.round((Date.now()-started)/1000)):null;
 const w={id:uniqueId(),day:ui.day,date:d.date,created:new Date().toISOString(),sets,warmups,notes:d.notes||'',durationSeconds,skippedExercises:[...(d.skipped||[])]};
 w.prHighlights=summarizeWorkout(w,state.workouts).prs;
 state.workouts.push(w);state.draft=null;state.restTimer=null;ui.summaryId=w.id;ui.tab='summary';location.hash='summary';save();render(true);notify('Training gespeichert · Zusammenfassung erstellt.');
}

function saveBody(form){const fd=new FormData(form),data={};for(const [key] of BODY_FIELDS){const v=fd.get(key);if(v===null||String(v).trim()==='')continue;const num=safeNum(v);if(!Number.isFinite(num)||num<=0||num>500){notify('Ungültiger Körperwert.');return}data[key]=num}if(!Object.keys(data).length){notify('Bitte mindestens einen Messwert eintragen.');return}state.body.push({id:uniqueId(),created:new Date().toISOString(),date:String(fd.get('date')),...data,note:String(fd.get('note')||'').trim()});save();render();notify('Körpermessung gespeichert.')}
function saveQuickWeight(form){const f=new FormData(form),w=safeNum(f.get('weight'));if(!Number.isFinite(w)||w<20||w>500){notify('Bitte gültiges Körpergewicht eingeben.');return}state.body.push({id:uniqueId(),created:new Date().toISOString(),date:today(),weight:w});save();render();notify('Gewicht gespeichert.')}
function saveCoach(form){const f=new FormData(form),sleep=safeNum(f.get('sleep')),fatigue=safeNum(f.get('fatigue')),back=safeNum(f.get('back'));if(sleep<0||sleep>24||fatigue<0||fatigue>10||back<0||back>10){notify('Check-in-Werte prüfen.');return}state.coach.checkins[today()]={shift:f.get('shift'),sleep,fatigue,back,redflag:f.has('redflag')};save();render();notify('Check-in gespeichert.')}
function saveRun(form){const f=new FormData(form),type=String(f.get('type')),minutes=safeNum(f.get('minutes')),distance=String(f.get('distance')||'').trim()===''?0:safeNum(f.get('distance'));if(!Number.isFinite(minutes)||minutes<=0||(type!=='airbike'&&(!Number.isFinite(distance)||distance<=0))){notify('Distanz und Dauer prüfen.');return}state.runs.push({id:uniqueId(),date:String(f.get('date')),created:new Date().toISOString(),type,minutes,distance:type==='airbike'?0:distance,hr:Number(f.get('hr'))||'',rpe:Number(f.get('rpe'))||3,note:String(f.get('note')||'')});save();render();notify('Ausdauer gespeichert.')}
function saveDuty(form){const f=new FormData(form);state.duty.push({id:uniqueId(),created:new Date().toISOString(),date:String(f.get('date')),shift:String(f.get('shift')),vest:Number(f.get('vest'))||0,back:Number(f.get('back'))||0,sleep:Number(f.get('sleep'))||0,note:String(f.get('note')||'')});save();render();notify('Diensteintrag gespeichert.')}
function exportData(){const content=makeBackup(state),file=new File([content],`winter-arc-v2-backup-${today()}.json`,{type:'application/json'});if(navigator.share&&navigator.canShare?.({files:[file]})){navigator.share({files:[file],title:'WINTER ARC – privates Backup'}).catch(err=>{if(err?.name!=='AbortError')downloadBackup(content)})}else downloadBackup(content)}
function downloadBackup(content){const blob=new Blob([content],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`winter-arc-v2-backup-${today()}.json`;document.body.append(link);link.click();setTimeout(()=>{link.remove();URL.revokeObjectURL(url)},1200);notify('Backup erzeugt. Sicher in Dateien ablegen.')}
async function importBackup(file){if(!file)return;try{const text=await file.text(),raw=JSON.parse(text),next=migrate(raw);if(!confirm('Import ersetzt alle derzeit gespeicherten WINTER-ARC-V2-Daten. Hast du vorher ein aktuelles Backup erstellt?'))return;state=next;if(!save()){throw new Error('Speicher konnte nicht aktualisiert werden.')}ui.bodyMetric='weight';ui.week=weekStart(today());ui.tab='home';render(true);notify('Backup importiert. Historie übernommen.')}catch(err){notify('Import fehlgeschlagen: '+String(err.message).slice(0,95))}}
function handleClick(event){const t=event.target.closest('button,[data-muscle]');if(!t)return;
 if(t.dataset.restAction){restAction(t.dataset.restAction);return}
 if(t.dataset.startDay){ui.day=t.dataset.startDay;ui.tab='training';location.hash='training';render(true);return}
 if(t.dataset.showSummary){ui.summaryId=t.dataset.showSummary;ui.tab='summary';location.hash='summary';render(true);return}
 if(t.dataset.range!==undefined){ui.progressDays=Number(t.dataset.range);render();return}
 if(t.dataset.moreTo){ui.moreSection=t.dataset.moreTo;ui.tab='more';location.hash='more';render(true);return}
 if(t.dataset.fillPrev){const key=t.dataset.fillPrev,d=ensureDraft(),slotId=key.split('#')[0],idx=Number(key.split('#').at(-1)),slot=state.plans[ui.day].find(x=>x.id===slotId);if(!slot)return;const prev=previousSets(state.workouts,effectiveExercise(slot,d).effectiveId)?.sets[idx];if(!prev)return;d.values[key]={...d.values[key],weight:String(prev.weight),reps:String(prev.reps),rir:String(prev.rir??'')};save();const sc=scrollY;render();scrollTo(0,sc);notify('Letzte Satzwerte übernommen.');return}
 if(t.dataset.fillAll){const d=ensureDraft(),slot=state.plans[ui.day].find(x=>x.id===t.dataset.fillAll);if(!slot)return;const previous=previousSets(state.workouts,effectiveExercise(slot,d).effectiveId)?.sets||[];if(!previous.length)return;let count=0;for(let j=0;j<Math.min(selectedSetCount(slot,d),previous.length);j++){const key=`${slot.id}#${j}`,v=d.values[key]||{};if(v.done)continue;d.values[key]={...v,weight:String(previous[j].weight),reps:String(previous[j].reps),rir:String(previous[j].rir??'')};count++}save();const sc=scrollY;render();scrollTo(0,sc);notify(count+' Sätze übernommen.');return}
 if(t.dataset.addSet){const d=ensureDraft(),slot=state.plans[ui.day].find(x=>x.id===t.dataset.addSet);if(!slot)return;const n=selectedSetCount(slot,d);if(n>=20)return;d.setCounts[slot.id]=n+1;save();const sc=scrollY;render();scrollTo(0,sc);return}
 if(t.dataset.removeSet){const d=ensureDraft(),[slotId,indexText]=t.dataset.removeSet.split('#'),slot=state.plans[ui.day].find(x=>x.id===slotId);if(!slot)return;const index=Number(indexText),count=selectedSetCount(slot,d);if(count<=1){notify('Mindestens ein Satz erforderlich. Sonst die Übung überspringen.');return}const v=d.values[`${slotId}#${index}`];if(v?.done&&!confirm('Abgeschlossenen Satz wirklich aus diesem Entwurf entfernen?'))return;removeSetValues(d,slotId,index,count);d.setCounts[slotId]=count-1;save();const sc=scrollY;render();scrollTo(0,sc);return}
 if(t.dataset.moveEx){const d=ensureDraft(),ordered=orderedExercises(state.plans[ui.day]||[],d).map(x=>x.id),i=ordered.indexOf(t.dataset.moveEx),j=i+Number(t.dataset.direction);if(i<0||j<0||j>=ordered.length)return;[ordered[i],ordered[j]]=[ordered[j],ordered[i]];d.order=ordered;save();render();return}
 if(t.dataset.skipEx){const d=ensureDraft(),id=t.dataset.skipEx;if(Object.entries(d.values||{}).some(([k,v])=>k.startsWith(id+'#')&&v?.done)&&!confirm('Diese Übung enthält abgehakte Sätze. Beim Überspringen werden sie nicht gespeichert. Trotzdem überspringen?'))return;d.skipped=[...new Set([...d.skipped,id])];save();render();return}
 if(t.dataset.restoreEx){const d=ensureDraft();d.skipped=d.skipped.filter(x=>x!==t.dataset.restoreEx);save();render();return}
 if(t.dataset.addLibrary){const ex=findLibrary(t.dataset.addLibrary);if(!ex)return;state.plans[ui.editDay].push({id:uniqueId(),catalogId:ex.id,name:ex.name,sets:2,reps:ex.defaultReps,note:'Aus Bibliothek hinzugefügt'});save();render();notify(ex.name+' zu Tag '+ui.editDay+' hinzugefügt.');return}

 if(t.dataset.moreSection){ui.moreSection=t.dataset.moreSection;render();return}
 if(t.dataset.openKnowledge){ui.moreSection='wissen';ui.tab='more';location.hash='more';render(true);return}
 if(t.dataset.tab){if(t.dataset.openKnowledge)ui.moreSection='wissen';ui.tab=t.dataset.tab;location.hash=ui.tab;render(true);return}
 if(t.dataset.day){if(state.draft?.day!==t.dataset.day&&Object.keys(state.draft?.values||{}).length&&!confirm('Ein offener Entwurf einer anderen Einheit ist vorhanden. Neue Einheit beginnen?'))return;ui.day=t.dataset.day;if(state.draft?.day!==ui.day)state.draft=null;save();render();return}
 if(t.dataset.atlasMode){ui.mode=t.dataset.atlasMode;render();return}if(t.dataset.atlasFace){ui.face=t.dataset.atlasFace;render();return}if(t.dataset.muscle){ui.muscle=t.dataset.muscle;render();return}
 if(t.dataset.benchmarkPhase){ui.benchmarkPhase=t.dataset.benchmarkPhase;render();return}
 if(t.dataset.week){ui.week=nextDate(ui.week,Number(t.dataset.week));render();return}if(t.dataset.month){const [y,m]=ui.month.split('-').map(Number);const d=new Date(y,m-1+Number(t.dataset.month),1);ui.month=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;render();return}
 if(t.dataset.calendarDate){ui.selectedDate=t.dataset.calendarDate;ui.month=ui.selectedDate.slice(0,7);if(t.dataset.openCalendar){ui.tab='analyze';location.hash='analyze';render(true)}else render();return}
 if(t.dataset.editDay){ui.editDay=t.dataset.editDay;render();return}if(t.dataset.phase){state.settings.trainPhase=t.dataset.phase;save();render();return}
 if(t.id==='save-workout'){saveWorkout();return}if(t.id==='clear-draft'){if(confirm('Unfertiges Training wirklich verwerfen?')){state.draft=null;save();render()}return}
 if(t.id==='export-data'||t.id==='export-data-alt'){exportData();return}if(t.id==='import-trigger'){$('#import-file')?.click();return}
 if(t.id==='apply-v73'){if(!confirm('WINTER ARC 7.3 mit fünf Einheiten aktivieren? Dein aktueller Plan wird intern als vorige Vorlage gesichert; abgeschlossene Trainingsdaten bleiben erhalten. Bitte vorher ein JSON-Backup exportieren.'))return;state.settings.planArchive={plans:clone(state.plans),activeProgram:state.settings.activeProgram,programLabels:clone(state.settings.programLabels||{})};state.plans=createProgram73();state.settings.activeProgram=PROGRAM_73_NAME;state.settings.programLabels={...PROGRAM_73_LABELS};state.settings.trainPhase='aufbau';state.draft=null;ui.day='A';ui.editDay='A';save();render(true);notify('WINTER ARC 7.3 aktiviert – fünf Trainingstage.');return}
  if(t.id==='restore-plan'){const old=state.settings.planArchive;if(!old||!confirm('Vorherigen Plan wiederherstellen? Abgeschlossene Workouts bleiben bestehen.'))return;state.plans=clone(old.plans);state.settings.activeProgram=old.activeProgram;state.settings.programLabels=clone(old.programLabels||{});delete state.settings.planArchive;state.draft=null;ui.day='A';ui.editDay='A';save();render(true);notify('Vorheriger Plan wiederhergestellt.');return}
  if(t.id==='apply-v52'){if(!confirm('WINTER ARC 5.2 als neuen Trainingsplan einstellen? Bestehende Pläne werden ersetzt; abgeschlossene Workouts bleiben erhalten. Vorher Backup empfohlen.'))return;state.plans=clone(DEFAULT_PLANS);state.settings.activeProgram='5.2';state.settings.programLabels={...EXERCISE_LABELS};state.draft=null;ui.day='A';ui.editDay='A';save();render();notify('WINTER ARC 5.2 aktiviert.');return}
 if(t.id==='add-ex'){state.plans[ui.editDay].push({id:uniqueId(),name:'Neue Übung (bitte benennen)',sets:2,reps:'10–15',note:''});save();render();return}
 if(t.dataset.removeEx){if(!confirm('Übung aus diesem Plan entfernen? Historische Sätze bleiben bestehen.'))return;state.plans[ui.editDay]=state.plans[ui.editDay].filter(x=>x.id!==t.dataset.removeEx);save();render();return}
 if(t.dataset.delete&&t.dataset.id){if(!confirm('Diesen Eintrag unwiderruflich aus V2 löschen?'))return;const list=state[t.dataset.delete];if(!Array.isArray(list))return;state[t.dataset.delete]=list.filter(x=>String(x.id)!==t.dataset.id);save();render();notify('Eintrag gelöscht.');return}
 if(t.id==='clear-v2'){if(confirm('ALLE V2-Einträge löschen? Das ist nur mit einem zuvor erstellten Backup rückgängig zu machen.')&&confirm('Wirklich alle V2-Daten löschen?')){localStorage.removeItem('winterArcOS_v2');state={...migrate({...state,version:2,workouts:[],runs:[],body:[],duty:[],morning:{},draft:null,exerciseNotes:{},coach:{checkins:{},shifts:{},longPlans:{}}})};save();render(true)}return}
}
function filterLibrary(root){const search=root.querySelector('[data-library-search]')?.value.trim().toLocaleLowerCase('de-DE')||'',muscle=root.querySelector('[data-library-muscle]')?.value||'all',equip=root.querySelector('[data-library-equipment]')?.value||'Alle';root.querySelectorAll('[data-library-item]').forEach(el=>{el.hidden=!!(search&&!el.dataset.searchText.includes(search))||(muscle!=='all'&&el.dataset.libraryMuscle!==muscle)||(equip!=='Alle'&&el.dataset.libraryEquipment!==equip);});}
function handleInput(event){const t=event.target;
 if(t.id==='knowledge-search'){const needle=t.value.trim().toLocaleLowerCase('de-DE');document.querySelectorAll('[data-knowledge-item]').forEach(el=>el.hidden=!!needle&&!el.dataset.searchText.includes(needle));return}
 if(t.dataset.librarySearch!==undefined){filterLibrary(t.closest('.panel')||t.closest('details')||document);return}
 if(t.dataset.swapSearch){const sel=document.querySelector(`select[data-alternative="${CSS.escape(t.dataset.swapSearch)}"]`);if(!sel)return;const q=t.value.trim().toLocaleLowerCase('de-DE');for(const opt of sel.options)opt.hidden=!!q&&!opt.textContent.toLocaleLowerCase('de-DE').includes(q);return}
 if(t.dataset.exNote){state.exerciseNotes??={};state.exerciseNotes[t.dataset.exNote]=t.value;save();return}

 if(t.dataset.set){const draft=ensureDraft(),v=draft.values[t.dataset.set]||{};v[t.dataset.field]=t.value;draft.values[t.dataset.set]=v;save();return}
 if(t.dataset.draftNotes!==undefined){ensureDraft().notes=t.value;save();return}
 if(t.dataset.draftDate!==undefined){ensureDraft().date=t.value;save();return}
 if(t.dataset.edit){const ex=state.plans[ui.editDay].find(x=>x.id===t.dataset.edit);if(!ex)return;if(t.dataset.prop==='sets')ex.sets=Math.max(1,Math.min(8,Math.round(Number(t.value)||1)));else ex[t.dataset.prop]=t.value;save();return}
}
function handleChange(event){const t=event.target;
 if(t.dataset.libraryMuscle!==undefined||t.dataset.libraryEquipment!==undefined){filterLibrary(t.closest('.panel')||t.closest('details')||document);return}
 if(t.dataset.exRest){const n=Math.round(safeNum(t.value));if(!Number.isFinite(n)||n<30||n>600){notify('Pausen nur zwischen 30 und 600 Sekunden.');t.value=exerciseRestSeconds(t.dataset.exRest);return}state.settings.exerciseRest??={};state.settings.exerciseRest[t.dataset.exRest]=n;save();notify('Übungspause gespeichert.');return}

 if(t.dataset.alternative){const draft=ensureDraft(),slotId=t.dataset.alternative,slot=state.plans[ui.day].find(e=>e.id===slotId);if(!slot)return;
  if(Object.entries(draft.values||{}).some(([k,v])=>k.startsWith(slotId+'#')&&v?.done)){notify('Erst abgeschlossene Sätze speichern oder die Alternative vor dem ersten Satz auswählen.');render();return}
  const option=[...alternativesFor(slot),...libraryAlternatives(slot)].find(a=>a.id===t.value);draft.swaps??={};if(option){if(Object.entries(draft.values).some(([k,v])=>k.startsWith(slotId+'#')&&(v?.weight||v?.reps))&&!confirm('Bereits eingegebene, noch nicht abgeschlossene Satzwerte für diese Übung zurücksetzen?')){render();return}for(const key of Object.keys(draft.values))if(key.startsWith(slotId+'#'))delete draft.values[key];draft.swaps[slotId]=option}else delete draft.swaps[slotId];save();const scroll=scrollY;render();scrollTo(0,scroll);notify(option?'Alternative für heute gewählt.':'Originalübung wieder aktiv.');return}
 if(t.id==='strength-lift'){ui.strengthLift=t.value;render();return}
 if(t.id==='strength-filter'){ui.strengthFilter=t.value;render();return}
 if(t.dataset.setCheck){const draft=ensureDraft(),v=draft.values[t.dataset.setCheck]||{};
 if(t.checked&&(!Number.isFinite(safeNum(v.reps))||safeNum(v.reps)<=0||!Number.isFinite(safeNum(v.weight))||safeNum(v.weight)<0)){t.checked=false;notify('Zuerst Gewicht und Wiederholungen eingeben.');return}
 v.done=t.checked;draft.values[t.dataset.setCheck]=v;save();
 const warm=t.dataset.setCheck.includes('#warm#');if(t.checked&&!warm){const slotId=t.dataset.setCheck.split('#')[0],slot=state.plans[ui.day].find(x=>x.id===slotId);if(slot)startRest(effectiveExercise(slot,draft).displayName,slotId)}
 const sc=scrollY;render();scrollTo(0,sc);return}
 if(t.dataset.morning){const day=today(),set=new Set(state.morning?.[day]||[]);if(t.checked)set.add(t.dataset.morning);else set.delete(t.dataset.morning);state.morning[day]=[...set];save();return}
 if(t.id==='body-metric'){ui.bodyMetric=t.value;render();return}if(t.id==='strength-ex'){ui.strengthEx=t.value;render();return}
 if(t.id==='import-file'){importBackup(t.files?.[0]);return}
 if(t.dataset.set){handleInput(event);return}
}
function handleSubmit(event){const f=event.target;if(!f.matches('form'))return;event.preventDefault();switch(f.id){case 'template-form':{const template=new FormData(f).get('template');const plan=templatePlans(template);if(!plan){notify('Vorlage nicht gefunden.');break}if(!confirm('Aktuellen A/B/C-Plan durch diese bearbeitbare Vorlage ersetzen? Deine früheren Workouts bleiben bestehen. Aktiven Trainingsentwurf zuvor sichern.'))break;state.plans=plan;state.settings.activeProgram=PROGRAM_TEMPLATES[template].name;state.settings.programLabels=templateLabels(template);state.draft=null;ui.day='A';ui.editDay='A';save();render();notify('Trainingsplan-Vorlage aktiviert.');break}case 'warmup-form':{const d=new FormData(f),target=safeNum(d.get('target')),bar=safeNum(d.get('bar'));if(!Number.isFinite(target)||target<=0||target>500||!Number.isFinite(bar)||bar<0||bar>50){notify('Rechner-Eingaben prüfen.');break}const ratios=String(d.get('ratios')||'40,60,80'),plates=String(d.get('plates')||'25,20,15,10,5,2.5,1.25'),r=ratios.split(',').map(x=>safeNum(x.trim())),pl=plates.split(',').map(x=>safeNum(x.trim()));if(!r.length||r.length>5||r.some(x=>!Number.isFinite(x)||x<=0||x>=100)||!pl.length||pl.length>12||pl.some(x=>!Number.isFinite(x)||x<=0||x>50)){notify('Prozente und Scheibengewichte prüfen (Komma-getrennte Zahlen).');break}ui.calc={target,bar,ratios,plates};render();notify('Aufwärmen & Scheiben berechnet.');break}case 'bench-height-form':{const h=safeNum(new FormData(f).get('heightCm'));if(!Number.isFinite(h)||h<140||h>240){notify('Bitte Körpergröße zwischen 140 und 240 cm angeben.');break}state.settings.heightCm=h;save();render();notify('Körpergröße aktualisiert.');break}case 'body-form':saveBody(f);break;case 'strength-entry-form':saveStrengthEntry(f);break;case 'rest-settings':saveRestSettings(f);break;case 'quick-weight':saveQuickWeight(f);break;case 'coach-form':saveCoach(f);break;case 'run-form':saveRun(f);break;case 'duty-form':saveDuty(f);break;case 'settings-form':{const d=new FormData(f);state.settings.raceDate=String(d.get('raceDate'));state.settings.goalPace=String(d.get('goalPace'));state.settings.goal=String(d.get('goal'));save();render();notify('Ziele gespeichert.');break}}}
document.addEventListener('click',handleClick);
document.addEventListener('input',handleInput);
document.addEventListener('change',handleChange);
document.addEventListener('submit',handleSubmit);
window.addEventListener('hashchange',()=>{const tab=location.hash.slice(1);if(['home','training','body','analyze','more','summary'].includes(tab)&&tab!==ui.tab){ui.tab=tab;render(true)}});
render();
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(err=>console.warn('Offline-Support konnte nicht aktiviert werden',err)));
